     "pre_process_code": "try:\n    import json\n    b = config.get('body')\n    if isinstance(b, dict):\n        q = json.loads(vars.get('cp_queue') or '[]')\n        q.append(str(b.get('product_id') or ''))\n        vars['cp_queue'] = json.dumps(q)\n        b['amount'] = round(float(str(b.get('amount')).replace(',', '')), 2)\n        b['date'] = str(b.get('date') or '').strip()[:10]\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    import json\n    result.pop('header', None)\n    q = json.loads(vars.get('cp_queue') or '[]')\n    pid = q.pop(0) if q else ''\n    vars['cp_queue'] = json.dumps(q)\n    d = result.get('data')\n    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'\n    fails = json.loads(vars.get('cp_fails') or '[]')\n    if ok:\n        vars['promise_count'] = str(int(vars.get('promise_count') or 0) + 1)\n        msg = 'Recorded for product ' + pid + '. Say: You will receive a text message confirming this promise. Then record the next confirmed product, or thank the customer and say goodbye.'\n    else:\n        fails.append(pid)\n        vars['cp_fails'] = json.dumps(fails)\n        if fails.count(pid) >= 2:\n            msg = 'NOT recorded, second failure for product ' + pid + '. Say you could not record this promise. Call add_note for product ' + pid + ' with reason service_error. Do not try again.'\n        else:\n            msg = 'NOT recorded for product ' + pid + '. Do not say it was recorded. Call create_promise once more with the same values now.'\n    if isinstance(d, dict):\n        d['what_to_do_next'] = msg\n    else:\n        result['data'] = dict(what_to_do_next=msg)\nexcept Exception:\n    pass\n"},
