     "pre_process_code": "try:\n    import json\n    b = config.get('body')\n    if isinstance(b, dict):\n        q = json.loads(vars.get('note_queue') or '[]')\n        q.append([str(b.get('product_id') or ''), str(b.get('reason') or '')])\n        vars['note_queue'] = json.dumps(q)\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    import json\n    result.pop('header', None)\n    q = json.loads(vars.get('note_queue') or '[]')\n    item = q.pop(0) if q else ['', '']\n    vars['note_queue'] = json.dumps(q)\n    d = result.get('data')\n    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'\n    if ok:\n        notes = json.loads(vars.get('notes_json') or '[]')\n        notes.append(item)\n        vars['notes_json'] = json.dumps(notes)\n        msg = 'Noted. Continue with the next product, or thank the customer and say goodbye.'\n    else:\n        msg = 'The note failed. Call add_note once more with the same values.'\n    if isinstance(d, dict):\n        d['what_to_do_next'] = msg\n    else:\n        result['data'] = dict(what_to_do_next=msg)\nexcept Exception:\n    pass\n"},
