     "function": {"name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Hand the call to a person. CALL it with restructuring for a new plan or lower instalments, support when a customer in hardship accepts the support team, general when the customer insists on a human.",
      "parameters": {"type": "object", "properties": {
