     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'\n    if ok:\n        vars['transfer_queue'] = vars.get('transfer_wanted') or 'general'\n        vars['call_state'] = 'transferred'\n    msg = 'Transferred. Do not call add_note or create_promise. Say a colleague will take over, thank them, say goodbye, then call end_call.' if ok else 'The transfer failed. Say so and offer to continue.'\n    if isinstance(d, dict):\n        d['what_to_do_next'] = msg\n    else:\n        result['data'] = dict(what_to_do_next=msg)\nexcept Exception:\n    pass\n"},
