   "excluded_nodes": ["setup", "load_account", "facts", "mark_wrong_number", "mark_deceased", "mark_unclear", "mark_no_callback", "mark_id_failed", "mark_declined", "account_error", "end_short", "end_callback", "end_deceased", "end_failed", "end_error"],
   "transitions": [{"target_node": "__previous__", "description": "always", "condition": {"operator": "always"}}]
  }
 },
