{
 "initial_node": "setup",
 "system_prompt": "You are Freya Bank's digital assistant, calling a customer. Speak English, one or two short sentences per turn, one question at a time. Before identity is verified never say collections, debt, payment, the product or why you are calling, to anyone, including relatives. If asked whether you are a robot or an AI, say you are Freya Bank's digital assistant and continue. If asked whether this is a scam, say they can verify the call by phoning Freya Bank's customer service number, and continue. Never invent figures, dates, terms or reasons: use only the facts you are given; if you do not know, say you do not have that information. Never offer a discount, a waiver, an instalment plan or any term not given to you. Say something was recorded only after the tool returned ok true. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result. Thank the customer and say goodbye before you end the call.",
 "test_variables": {
  "customer_id": "c_test01",
  "first_name": "Daniel",
  "last_name": "Reyes",
  "title": "Mr",
  "now": "2026-10-14T11:00"
 },
 "nodes": {
  "setup": {
   "name": "setup",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "opening",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
     "parameters": {"type": "object", "properties": {
      "code": {"type": "string", "default": "import datetime\nimport json\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOLS = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef parse_holidays(values):\n    out = set()\n    for v in values or []:\n        try:\n            out.add(datetime.date.fromisoformat(str(v)[:10]))\n        except ValueError:\n            pass\n    return out\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays, include_today=False):\n    if include_today and is_business_day(d, holidays):\n        return d\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef spoken_date(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ntry:\n    now = parse_now(vars.get('now'))\n    hol = parse_holidays(HOLS)\n    today = now.date()\n    hm = now.strftime('%H:%M')\n    opts = []\n    if is_business_day(today, hol) and hm < '19:00':\n        opts.append('today, ' + spoken_date(today) + ' (date ' + today.isoformat() + '), at a time later than ' + hm + ' and from 10:00 to 19:00')\n    nb = next_business_day(today, hol)\n    opts.append(spoken_date(nb) + ' (date ' + nb.isoformat() + '), from 10:00 to 19:00')\n    vars['callback_window_text'] = 'It is now ' + spoken_date(today) + ', ' + hm + '. A callback can be booked only on: ' + '; or '.join(opts) + '. 10:00 and 19:00 are both allowed. Any other day or time is outside the window.'\n    vars['calendar_state'] = 'ok'\nexcept Exception:\n    vars['callback_window_text'] = 'A callback can be booked on the next business day from 10:00 to 19:00.'\n    vars['calendar_state'] = 'error'\nvars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'unclear'\nvars['promise_count'] = '0'\nvars['call_state'] = 'open'\nvars['id_state'] = 'pending'\nvars['notes_json'] = '[]'\nvars['product_order'] = '[]'\nvars['transfer_queue'] = ''\nvars['facts_text'] = ''\n"},
      "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [{"target_node": "opening", "description": "always", "condition": {"operator": "always"}}]
  },
  "opening": {
   "name": "opening",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Hello, this is a digital assistant calling from Freya Bank. This call is recorded. Am I speaking with {{title}} {{last_name}}?"},
   "on_enter_first_entry_only": true,
   "task_message": "Find out whether you are speaking with {{title}} {{last_name}}. Only yes, that's me, speaking, or the customer's own name confirms it. Hello, go ahead or who is this do not. If it is unclear, ask once more exactly: Am I speaking with {{title}} {{last_name}}? If they asked a question, answer it first; the ask after it is the second ask. Say nothing about why you are calling. No tool call is allowed except end_call right after you said goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "who", "type": "string", "enum_values": ["stay", "customer", "someone_else", "wrong_number", "deceased", "unclear_twice"], "description": "customer: the person confirmed with yes, that's me, speaking or their own name. someone_else: another person answered. wrong_number: the number does not belong to the customer. deceased: the customer has died. unclear_twice: you already asked twice and still no confirmation. Else stay.", "min_confidence": 0.6}
   ],
   "max_node_turns": 4,
   "max_turn_transition": "mark_unclear",
   "transitions": [
    {"target_node": "identity", "description": "The customer confirmed", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "customer"}]}},
    {"target_node": "third_party", "description": "Someone else answered", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "someone_else"}]}},
    {"target_node": "mark_wrong_number", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "wrong_number"}]}},
    {"target_node": "mark_deceased", "description": "Customer deceased", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "deceased"}]}},
    {"target_node": "mark_unclear", "description": "Still unclear after the second ask", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "unclear_twice"}]}}
   ]
  },
  "third_party": {
   "name": "third_party",
   "node_type": "conversation",
   "task_message": "You are not speaking with the customer. Say nothing beyond your opening sentence: no reason for the call and nothing about any account, even to a relative or someone who offers to pay. Never ask them security questions. Ask when {{title}} {{last_name}} can be reached. {{callback_window_text}} When they give a day and a time inside that window, call schedule_callback with date (YYYY-MM-DD) and time (HH:MM). If the day or time is outside the window, ask once for another time; if that is also outside it, do not schedule. After every tool result, either speak or call the next tool. Follow what_to_do_next in a tool result. Call end_call only right after you said goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0},
     "function": {"name": "schedule_callback", "handler": "__function__:api_call", "description": "Book a callback. CALL it as soon as the person gives a day and time inside the window.",
      "parameters": {"type": "object", "properties": {
       "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/schedule_callback"},
       "method": {"type": "string", "default": "POST"},
       "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
       "body": {"type": "object", "required": ["customer_id", "date", "time"], "properties": {
        "customer_id": {"type": "string", "default": "{{customer_id}}"},
        "date": {"type": "string", "description": "The callback day as YYYY-MM-DD, inside the window.", "default": "{{date}}"},
        "time": {"type": "string", "description": "The callback time as HH:MM, from 10:00 to 19:00.", "default": "{{time}}"}}}}}},
     "pre_process_code": "try:\n    import re\n    b = config.get('body')\n    if isinstance(b, dict):\n        m = re.match(r'^\\s*(\\d{1,2})[:.h]?(\\d{2})?', str(b.get('time') or ''))\n        if m:\n            b['time'] = m.group(1).zfill(2) + ':' + (m.group(2) or '00')\n        b['date'] = str(b.get('date') or '').strip()[:10]\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':\n        vars['close_outcome'] = 'not_reached'\n        vars['close_reason'] = 'callback'\n        vars['call_state'] = 'callback_booked'\n        d['what_to_do_next'] = 'Booked. Thank them and say goodbye.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'Not booked. Do not say it was booked. Ask once for another time inside the window.'\n    else:\n        result['data'] = dict(what_to_do_next='Not booked. Do not say it was booked. Ask once for another time inside the window.')\nexcept Exception:\n    pass\n"},
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "tp_state", "type": "string", "enum_values": ["stay", "no_time", "wrong_number", "deceased"], "description": "no_time: the second offered day or time is also outside the window, or the person gives no time after the second ask. wrong_number: the number does not belong to the customer. deceased: the customer has died. Else stay.", "min_confidence": 0.7}
   ],
   "max_node_turns": 6,
   "max_turn_transition": "mark_no_callback",
   "transitions": [
    {"target_node": "end_callback", "description": "Callback booked", "condition": {"logic": "or", "conditions": [{"variable": "call_state", "operator": "equals", "operand": "callback_booked"}]}},
    {"target_node": "mark_wrong_number", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "tp_state", "operator": "equals", "operand": "wrong_number"}]}},
    {"target_node": "mark_deceased", "description": "Deceased", "condition": {"logic": "or", "conditions": [{"variable": "tp_state", "operator": "equals", "operand": "deceased"}]}},
    {"target_node": "mark_no_callback", "description": "No time inside the window", "condition": {"logic": "or", "conditions": [{"variable": "tp_state", "operator": "equals", "operand": "no_time"}]}}
   ]
  },
  "identity": {
   "name": "identity",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Thank you. First I need to check your identity. What is your date of birth?"},
   "on_enter_first_entry_only": true,
   "task_message": "Ask two security questions, one at a time: first the date of birth, then the last four digits of the phone number on file. Call verify_identity once per answer: field date_of_birth with the answer as YYYY-MM-DD (convert spoken dates; a date given only as numbers is day, then month, then year), or field phone_last4 with four digits. Say nothing about why you are calling or about any account before both pass. If the customer does not want to answer, or asks what the call is about instead of answering, explain once that the questions protect their account. If they ask for a human, ask once whether you can help first; if they insist, call transfer_to_agent with queue general, then say a colleague will take over, say goodbye and call end_call. After every tool result, either speak or call the next tool. Follow what_to_do_next in a tool result.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 1},
     "function": {"name": "verify_identity", "handler": "__function__:api_call", "description": "Check one security answer. CALL it every time the customer answers a security question.",
      "parameters": {"type": "object", "properties": {
       "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"},
       "method": {"type": "string", "default": "POST"},
       "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
       "body": {"type": "object", "required": ["customer_id", "field", "answer"], "properties": {
        "customer_id": {"type": "string", "default": "{{customer_id}}"},
        "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "description": "Which question was answered.", "default": "{{field}}"},
        "answer": {"type": "string", "description": "date_of_birth: YYYY-MM-DD. phone_last4: four digits.", "default": "{{answer}}"}}}}}},
     "pre_process_code": "try:\n    import re\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = str(b.get('answer') or '').strip()\n        if b.get('field') == 'phone_last4':\n            digits = re.sub(r'\\D', '', a)\n            b['answer'] = digits[-4:] if len(digits) >= 4 else digits\n        else:\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                b['answer'] = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict):\n        if str(d.get('all_verified')).lower() == 'true':\n            vars['id_state'] = 'passed'\n            d['what_to_do_next'] = 'Identity confirmed. Say thank you in one short sentence.'\n        elif d.get('hint') == 'day_month_swapped':\n            d['what_to_do_next'] = 'Ask the customer to say the date of birth again with the month as a word. This retry does not count as a wrong answer.'\n        elif str(d.get('verified')).lower() == 'true':\n            d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the phone number on file.'\n        elif str(d.get('wrong_answers_left')) == '0':\n            vars['id_state'] = 'failed'\n            d['what_to_do_next'] = 'The check failed. Say nothing about the account.'\n        elif d.get('wrong_answers_left') is None:\n            d['what_to_do_next'] = 'The answer could not be checked. Ask the same question again.'\n        else:\n            d['what_to_do_next'] = 'That answer is wrong. Ask the same question once more.'\n    else:\n        result['data'] = dict(what_to_do_next='The check did not work. Ask the same question again.')\nexcept Exception:\n    pass\n"},
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0},
     "function": {"name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Hand the call to a person. CALL it only when the customer insists on a human after you asked once whether you can help.",
      "parameters": {"type": "object", "properties": {
       "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/transfer_to_agent"},
       "method": {"type": "string", "default": "POST"},
       "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
       "body": {"type": "object", "required": ["customer_id", "queue"], "properties": {
        "customer_id": {"type": "string", "default": "{{customer_id}}"},
