     "parameters": {"type": "object", "properties": {
      "code": {"type": "string", "default": "import datetime\nimport json\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOLS = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef parse_holidays(values):\n    out = set()\n    for v in values or []:\n        try:\n            out.add(datetime.date.fromisoformat(str(v)[:10]))\n        except ValueError:\n            pass\n    return out\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays, include_today=False):\n    if include_today and is_business_day(d, holidays):\n        return d\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef add_business_days(d, n, holidays):\n    for _ in range(int(n)):\n        d = next_business_day(d, holidays)\n    return d\n\ndef week_monday(d):\n    return d - datetime.timedelta(days=d.weekday())\n\ndef last_business_day_of_week(d, holidays):\n    day = week_monday(d) + datetime.timedelta(days=4)\n    while day >= week_monday(d):\n        if is_business_day(day, holidays):\n            return day\n        day = day - datetime.timedelta(days=1)\n    return None\n\ndef spoken_date(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ndef money(amount):\n    v = round(float(amount), 2)\n    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)\n\ndef as_list(value):\n    if isinstance(value, list):\n        return value\n    if isinstance(value, str):\n        try:\n            value = json.loads(value)\n        except ValueError:\n            return []\n    if isinstance(value, dict):\n        return [value]\n    return value if isinstance(value, list) else []\n\ndef list_from_vars(vars, name, prefixes):\n    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []\n    if found:\n        return found\n    for prefix in prefixes:\n        rows = dict()\n        start = prefix + '.'\n        for key, value in vars.items():\n            if not str(key).startswith(start):\n                continue\n            rest = str(key)[len(start):]\n            idx, _, field = rest.partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), dict())[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\n\nBANDS = [(1, 7, 12, 1, 'early'), (8, 45, 7, 2, 'late')]\nFLOOR = dict(credit_card='minimum_payment', personal_loan='instalment_amount', car_loan='instalment_amount')\ntry:\n    now = parse_now(vars.get('now'))\n    hol = parse_holidays(HOLS)\n    today = now.date()\n    prods = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])\n    wk = last_business_day_of_week(today, hol)\n    if wk is None or wk <= today:\n        wk = last_business_day_of_week(today + datetime.timedelta(days=7), hol)\n    lines, say, stm, order, dls = [], [], [], [], []\n    for n, p in enumerate(prods, 1):\n        t = str(p.get('type') or '')\n        if t == 'credit_card':\n            name = 'credit card ending ' + str(p.get('card_last4') or '')\n        elif t == 'car_loan':\n            name = 'car loan'\n        else:\n            name = 'personal loan'\n        due = float(p.get('past_due') or 0)\n        days = int(float(p.get('days_late') or 0))\n        floor = float(p.get(FLOOR.get(t, 'instalment_amount')) or 0)\n        band = BANDS[0] if days <= 7 else BANDS[1]\n        dl = add_business_days(today, band[2], hol)\n        a1 = min(wk, dl)\n        pid = str(p.get('product_id') or '')\n        order.append(pid)\n        dls.append(dl)\n        stm.append('Your ' + name + ' has ' + money(due) + ' past due and is ' + str(days) + ' days late.')\n        lines.append('Product ' + str(n) + ': ' + name + ' (product_id ' + pid + '). Past due: ' + money(due) + '. Days late: ' + str(days) + '. Floor (lowest amount): ' + money(floor) + '. Band: ' + band[4] + '. Deadline (latest promise date): ' + spoken_date(dl) + ' (' + dl.isoformat() + '). Persuasion attempts allowed: ' + str(band[3]) + '. Attempt 1 date: ' + spoken_date(a1) + ' (' + a1.isoformat() + ').')\n        s = ['Product ' + str(n) + ' (' + name + '):']\n        s.append('  Attempt 1: Could you pay the full ' + money(due) + ' on ' + spoken_date(a1) + '?')\n        s.append('  Attempt 1 after the full amount was too much: Could you pay ' + money(floor) + ' on ' + spoken_date(a1) + '? The rest stays overdue.')\n        s.append('  Floor offer (once, when the full amount is too much): Could you pay ' + money(floor) + ' instead? The rest stays overdue.')\n        s.append('  Below the floor (once): I cannot record an amount below ' + money(floor) + '. Could you pay ' + money(floor) + '? The rest stays overdue.')\n        s.append('  Date after the deadline: The latest date I can record is ' + spoken_date(dl) + '. Could you pay by then?')\n        if band[3] >= 2:\n            s.append('  Attempt 2: Could you pay ' + money(floor) + ' on ' + spoken_date(dl) + '? The rest stays overdue.')\n        else:\n            s.append('  No attempt 2 for this product: after attempt 1 is refused, stop.')\n        say.append('\\n'.join(s))\n    tbl = []\n    for i in range(0, 22):\n        d = today + datetime.timedelta(days=i)\n        ok = [str(k + 1) for k, x in enumerate(dls) if d <= x]\n        row = spoken_date(d) + ' (' + d.isoformat() + '): '\n        if is_business_day(d, hol):\n            row += 'business day'\n        else:\n            row += 'NOT a business day, next business day ' + spoken_date(next_business_day(d, hol))\n        row += '; within the deadline of product: ' + (', '.join(ok) if ok else 'none')\n        tbl.append(row)\n    wd = []\n    for i in range(7):\n        this_d = week_monday(today) + datetime.timedelta(days=i)\n        wd.append('this ' + WEEKDAYS[i].title() + ' = ' + spoken_date(this_d) + '; next ' + WEEKDAYS[i].title() + ' = ' + spoken_date(this_d + datetime.timedelta(days=7)))\n    vars['facts_text'] = 'Today is ' + spoken_date(today) + ' (' + today.isoformat() + '). Amounts are in the account currency.\\n' + '\\n'.join(lines) + '\\nSay these sentences exactly when they apply:\\n' + '\\n'.join(say) + '\\nDate table (look dates up here, never compute them):\\n' + '\\n'.join(tbl) + '\\nWeekday words:\\n' + '\\n'.join(wd)\n    vars['statements_text'] = ' '.join(stm)\n    vars['product_order'] = json.dumps(order)\n    vars['product_count'] = str(len(order))\n    vars['pay_today_q'] = 'Can you make this payment today?' if len(order) <= 1 else 'Can you pay all of them today?'\n    vars['facts_state'] = 'ok' if order else 'empty'\nexcept Exception:\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['statements_text'] = ''\n    vars['pay_today_q'] = 'Can you make this payment today?'\n    vars['product_count'] = '0'\n    vars['facts_state'] = 'error'\nvars['close_outcome'] = 'no_promise'\nvars['close_reason'] = 'refused'\n"},
      "timeout_ms": {"type": "number", "default": 10000}}}}}
