     "pre_process_code": "try:\n    import json\n    b = config.get('body')\n    if isinstance(b, dict):\n        q = json.loads(vars.get('note_queue') or '[]')\n        q.append([str(b.get('product_id') or ''), str(b.get('reason') or '')])\n        vars['note_queue'] = json.dumps(q)\nexcept Exception:\n    pass\n",
