  {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0, "alwaysRunsAt": ["end_of_call"]},
   "function": {"name": "close_call", "handler": "__function__:api_call", "description": "Record how the call ended.",
    "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call"},
     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "required": ["customer_id", "outcome"], "properties": {
      "customer_id": {"type": "string", "default": "{{customer_id}}"},
      "outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"], "default": "{{close_outcome}}", "description": "How the call ended."},
      "reason": {"type": "string", "default": "{{close_reason}}", "description": "Leave out for promise and paid."}}}}}},
   "pre_process_code": "try:\n    import json\n    b = config.get('body')\n    if isinstance(b, dict):\n        out = vars.get('close_outcome') or 'not_reached'\n        rsn = vars.get('close_reason') or 'unclear'\n        q = vars.get('transfer_queue') or ''\n        pc = int(vars.get('promise_count') or 0)\n        notes = json.loads(vars.get('notes_json') or '[]')\n        order = json.loads(vars.get('product_order') or '[]')\n        if q:\n            out, rsn = 'transferred', dict(restructuring='restructuring', general='human', support='support').get(q, 'human')\n        elif pc > 0:\n            out, rsn = 'promise', ''\n        elif notes:\n            last = dict()\n            for n in notes:\n                last[n[0]] = n[1]\n            vals = [last[p] for p in order if p in last] or list(last.values())\n            if all(v == 'paid' for v in vals):\n                out, rsn = 'paid', ''\n            else:\n                out, rsn = 'no_promise', [v for v in vals if v != 'paid'][0]\n        b['outcome'] = out\n        if rsn and out not in ('promise', 'paid'):\n            b['reason'] = rsn\n        else:\n            b.pop('reason', None)\nexcept Exception:\n    pass\n"}
 ]
}

